{
  "$schema": "https://opencode.ai/config.json",
  "providers": {
    "lmstudio": {
      "settings": { "baseURL": "http://gpu-host:1234/v1" },
    },
    "vllm": {
      "settings": { "baseURL": "http://gpu-host:8000/v1" },
    },
  },
}

// select a discovered model:
{ "model": "vllm/Qwen/Qwen3-Coder-30B-A3B-Instruct" }
// authenticated vLLM:
{ "providers": { "vllm": { "settings": { "baseURL": "http://127.0.0.1:9000/v1", "apiKey": "{env:VLLM_API_KEY}" } } } }
// disable discovery:
{ "plugins": ["-opencode.provider.vllm"] }

{
  "$schema": "https://opencode.ai/config.json",
  "provider": {
    "ollama": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "Ollama",
      "options": {
        "baseURL": "http://localhost:11434/v1"
      },
      "models": {
        "qwen3.5": {
          "name": "qwen3.5"
        }
      }
    }
  }
}
// "OpenCode requires a context length of 64k or higher."  Launch: ollama launch opencode   |  OLLAMA_CONTEXT_LENGTH=64000 ollama serve (https://docs.ollama.com/context-length)
